/* @lc app=leetcode id=2876 lang=kotlin */ class Solution { fun countVisitedNodes(edges: List<Int>): IntArray = edges.size.let { n -> IntArray(n).also { d -> edges.forEach { d[it]++ } }.let { d -> generateSequence((0 until n).filter { d[it] == 0 }) { f -> f.mapNotNull { u -> edges[u].takeIf { v -> --d[v] == 0 } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { peeled -> IntArray(n).also { ans -> (0 until n).filter { d[it] > 0 }.forEach { i -> if (ans[i] == 0) generateSequence(i) { edges[it].takeIf { v -> v != i } }.toList().let { cyc -> cyc.forEach { ans[it] = cyc.size } } } }.also { ans -> peeled.reversed().forEach { u -> ans[u] = ans[edges[u]] + 1 } } } } } }